package com.lucerne.ui;

import com.lucerne.app.AppSession;
import com.lucerne.dao.POSDAO;
import com.lucerne.dao.QueryDAO;
import com.lucerne.model.CartItem;
import com.lucerne.service.SaleService;
import com.lucerne.service.ReceiptService;
import com.lucerne.ui.dialogs.ReceiptPreviewDialog;
import com.lucerne.ui.components.LoadingPane;
import com.lucerne.util.AlertUtil;
import javafx.beans.property.ReadOnlyObjectWrapper;
import javafx.collections.FXCollections;
import javafx.concurrent.Task;
import javafx.geometry.Insets;
import javafx.geometry.Pos;
import javafx.scene.control.*;
import javafx.scene.image.Image;
import javafx.scene.image.ImageView;
import javafx.scene.layout.*;

import java.math.BigDecimal;
import java.util.List;

public final class POSView extends StackPane {
    private final POSDAO dao=new POSDAO();private final SaleService saleService=new SaleService();private final ReceiptService receiptService=new ReceiptService();private final FlowPane products=new FlowPane(12,12);
    private final TextField search=new TextField();private final ComboBox<QueryDAO.Option> category=new ComboBox<>();private final ComboBox<QueryDAO.Option> customer=new ComboBox<>();
    private final TableView<CartItem> cart=new TableView<>();private final Label subtotal=new Label("0.00"),discountLabel=new Label("0.00"),total=new Label("0.00"),change=new Label("0.00");private final TextField discountCode=new TextField(),paid=new TextField();private final ComboBox<String> payment=new ComboBox<>();private final LoadingPane loading=new LoadingPane();private Integer discountId;private BigDecimal discountAmount=BigDecimal.ZERO;
    public POSView(){getChildren().addAll(build(),loading);loadLookups();loadProducts();}
    private BorderPane build(){BorderPane root=new BorderPane();root.setPadding(new Insets(24));root.getStyleClass().add("page-root");Label title=new Label("Point of Sale");title.getStyleClass().add("page-title");Label desc=new Label("Search products, validate branch stock, apply discounts and complete one atomic transaction.");desc.getStyleClass().add("page-description");TextField barcode=search;barcode.setPromptText("Search name, SKU or scan barcode");barcode.setPrefWidth(320);Button find=new Button("Search");find.getStyleClass().add("primary-button");find.setOnAction(e->loadProducts());category.setPromptText("All categories");category.setOnAction(e->loadProducts());HBox filters=new HBox(10,barcode,category,find);filters.setAlignment(Pos.CENTER_LEFT);VBox top=new VBox(12,new VBox(4,title,desc),filters);root.setTop(top);BorderPane.setMargin(top,new Insets(0,0,16,0));ScrollPane productScroll=new ScrollPane(products);productScroll.setFitToWidth(true);productScroll.setHbarPolicy(ScrollPane.ScrollBarPolicy.NEVER);products.setPadding(new Insets(4));root.setCenter(productScroll);root.setRight(cartPanel());BorderPane.setMargin(root.getRight(),new Insets(0,0,0,18));search.setOnAction(e->loadProducts());return root;}
    private VBox cartPanel(){VBox panel=new VBox(12);panel.getStyleClass().add("content-card");panel.setPadding(new Insets(16));panel.setPrefWidth(470);Label heading=new Label("Current sale");heading.getStyleClass().add("section-title");customer.setPromptText("Walk-in customer");customer.setMaxWidth(Double.MAX_VALUE);TableColumn<CartItem,String> name=new TableColumn<>("Product");name.setCellValueFactory(v->new ReadOnlyObjectWrapper<>(v.getValue().productName()+"\n"+v.getValue().color()+" / "+v.getValue().size()));name.setPrefWidth(170);TableColumn<CartItem,Integer> qty=new TableColumn<>("Qty");qty.setCellValueFactory(v->v.getValue().quantityProperty().asObject());qty.setCellFactory(c->new TableCell<>(){private final Spinner<Integer> spinner=new Spinner<>(1,999,1);{spinner.setEditable(true);spinner.valueProperty().addListener((o,a,b)->{CartItem item=getTableRow().getItem();if(item!=null){item.setQuantity(b);updateTotals();}});}protected void updateItem(Integer item,boolean empty){super.updateItem(item,empty);if(empty){setGraphic(null);}else{CartItem ci=getTableRow().getItem();if(ci!=null)spinner.getValueFactory().setValue(ci.quantity());setGraphic(spinner);}}});qty.setPrefWidth(90);TableColumn<CartItem,String> line=new TableColumn<>("Total");line.setCellValueFactory(v->new ReadOnlyObjectWrapper<>(String.format("%.2f",v.getValue().lineTotal())));line.setPrefWidth(90);TableColumn<CartItem,Void> remove=new TableColumn<>("");remove.setCellFactory(c->new TableCell<>(){private final Button b=new Button("×");{b.getStyleClass().add("danger-button");b.setOnAction(e->{CartItem item=getTableRow().getItem();cart.getItems().remove(item);updateTotals();});}protected void updateItem(Void x,boolean empty){super.updateItem(x,empty);setGraphic(empty?null:b);}});remove.setPrefWidth(45);cart.getColumns().add(name);cart.getColumns().add(qty);cart.getColumns().add(line);cart.getColumns().add(remove);cart.setPrefHeight(300);cart.setPlaceholder(new Label("Add products to begin."));HBox discountRow=new HBox(8,discountCode);discountCode.setPromptText("Discount code");Button applyDiscount=new Button("Apply");applyDiscount.setOnAction(e->applyDiscount());discountRow.getChildren().add(applyDiscount);payment.getItems().addAll("CASH","CARD","MIXED","BANK_TRANSFER");payment.setValue("CASH");paid.setPromptText("Paid amount");paid.textProperty().addListener((o,a,b)->updateChange());GridPane totals=new GridPane();totals.setHgap(16);totals.setVgap(8);totals.addRow(0,new Label("Subtotal"),subtotal);totals.addRow(1,new Label("Discount"),discountLabel);Label totalText=new Label("Total");totalText.getStyleClass().add("total-label");total.getStyleClass().add("total-value");totals.addRow(2,totalText,total);totals.addRow(3,new Label("Change"),change);Button complete=new Button("Complete sale");complete.getStyleClass().add("primary-button");complete.setMaxWidth(Double.MAX_VALUE);complete.setOnAction(e->complete());Button clear=new Button("Clear cart");clear.setMaxWidth(Double.MAX_VALUE);clear.setOnAction(e->{cart.getItems().clear();discountId=null;discountAmount=BigDecimal.ZERO;updateTotals();});panel.getChildren().addAll(heading,new Label("Customer"),customer,cart,discountRow,new Label("Payment method"),payment,paid,totals,complete,clear);VBox.setVgrow(cart,Priority.ALWAYS);return panel;}
    private void loadLookups(){Task<LookupData> t=new Task<>(){protected LookupData call()throws Exception{return new LookupData(dao.categories(),dao.customers());}};t.setOnSucceeded(e->{category.getItems().setAll(new QueryDAO.Option(null,"All categories"));category.getItems().addAll(t.getValue().categories());category.getSelectionModel().selectFirst();customer.getItems().setAll(new QueryDAO.Option(null,"Walk-in customer"));customer.getItems().addAll(t.getValue().customers());customer.getSelectionModel().selectFirst();});Thread x=new Thread(t);x.setDaemon(true);x.start();}
    private int branchId(){if(AppSession.current().branchId()==null)throw new IllegalStateException("The logged-in cashier is not assigned to a branch.");return AppSession.current().branchId();}
    private void loadProducts(){Integer cat=category.getValue()==null||category.getValue().id()==null?null:((Number)category.getValue().id()).intValue();loading.show("Loading available products…");Task<List<POSDAO.VariantRow>> t=new Task<>(){protected List<POSDAO.VariantRow> call()throws Exception{return dao.search(branchId(),search.getText(),cat);}};t.setOnSucceeded(e->{renderProducts(t.getValue());loading.hide();});t.setOnFailed(e->{loading.hide();AlertUtil.error("Products unavailable","Check cashier branch assignment and database connection.");});Thread x=new Thread(t,"pos-products");x.setDaemon(true);x.start();}
    private void renderProducts(List<POSDAO.VariantRow> variants){products.getChildren().clear();for(POSDAO.VariantRow v:variants)products.getChildren().add(productCard(v));if(variants.isEmpty())products.getChildren().add(new Label("No in-stock products match the search."));}
    private VBox productCard(POSDAO.VariantRow v){VBox card=new VBox(8);card.getStyleClass().add("product-card");card.setPadding(new Insets(12));card.setPrefWidth(190);ImageView image=new ImageView();image.setFitWidth(160);image.setFitHeight(170);image.setPreserveRatio(true);try{var stream=getClass().getResourceAsStream("/"+v.imagePath());if(stream!=null)image.setImage(new Image(stream));}catch(Exception ignored){}Label name=new Label(v.name());name.getStyleClass().add("product-name");name.setWrapText(true);Label variant=new Label(v.color()+" · "+v.size()+" · Stock "+v.stock());variant.getStyleClass().add("secondary-text");Label price=new Label(String.format("$%,.2f",v.price()));price.getStyleClass().add("product-price");Button add=new Button("Add to cart");add.getStyleClass().add("primary-button");add.setMaxWidth(Double.MAX_VALUE);add.setOnAction(e->addToCart(v));card.getChildren().addAll(image,name,variant,price,add);return card;}
    private void addToCart(POSDAO.VariantRow v){for(CartItem item:cart.getItems())if(item.variantId()==v.variantId()){item.setQuantity(item.quantity()+1);cart.refresh();updateTotals();return;}cart.getItems().add(new CartItem(v.variantId(),v.productId(),v.name(),v.size(),v.color(),v.price(),v.stock()));updateTotals();}
    private BigDecimal subtotalValue(){return cart.getItems().stream().map(CartItem::lineTotal).reduce(BigDecimal.ZERO,BigDecimal::add);}
    private void updateTotals(){BigDecimal sub=subtotalValue();if(discountAmount.compareTo(sub)>0){discountAmount=BigDecimal.ZERO;discountId=null;}BigDecimal finalTotal=sub.subtract(discountAmount);subtotal.setText(String.format("%,.2f",sub));discountLabel.setText(String.format("%,.2f",discountAmount));total.setText(String.format("%,.2f",finalTotal));if(paid.getText().isBlank()&&payment.getValue()!=null&&!payment.getValue().equals("CASH"))paid.setText(finalTotal.toPlainString());updateChange();cart.refresh();}
    private void updateChange(){try{BigDecimal p=new BigDecimal(paid.getText().isBlank()?"0":paid.getText());BigDecimal t=new BigDecimal(total.getText().replace(",",""));change.setText(String.format("%,.2f",p.subtract(t).max(BigDecimal.ZERO)));}catch(Exception e){change.setText("0.00");}}
    private void applyDiscount(){BigDecimal sub=subtotalValue();Task<POSDAO.DiscountResult> t=new Task<>(){protected POSDAO.DiscountResult call()throws Exception{return dao.validateDiscount(discountCode.getText(),sub);}};loading.show("Validating discount…");t.setOnSucceeded(e->{loading.hide();discountId=t.getValue().discountId();discountAmount=t.getValue().amount();updateTotals();AlertUtil.info("Discount",t.getValue().message());});t.setOnFailed(e->{loading.hide();discountId=null;discountAmount=BigDecimal.ZERO;updateTotals();AlertUtil.warning("Discount not applied","The code is invalid, expired or does not meet the minimum purchase.");});Thread x=new Thread(t);x.setDaemon(true);x.start();}
    private void complete(){if(cart.getItems().isEmpty()){AlertUtil.warning("Empty cart","Add at least one product.");return;}try{BigDecimal paidValue=new BigDecimal(paid.getText().isBlank()?"0":paid.getText());Integer customerId=customer.getValue()==null||customer.getValue().id()==null?null:((Number)customer.getValue().id()).intValue();List<CartItem> snapshot=List.copyOf(cart.getItems());loading.show("Completing sale and updating stock…");Task<SaleService.SaleResult> t=new Task<>(){protected SaleService.SaleResult call()throws Exception{return saleService.completeSale(branchId(),customerId,snapshot,discountId,discountAmount,payment.getValue(),paidValue);}};t.setOnSucceeded(e->{loading.hide();var r=t.getValue();AlertUtil.info("Sale completed","Receipt: "+r.receiptNumber()+"\nTotal: "+String.format("$%,.2f",r.total())+"\nChange: "+String.format("$%,.2f",r.change()));cart.getItems().clear();discountCode.clear();paid.clear();discountId=null;discountAmount=BigDecimal.ZERO;updateTotals();loadProducts();showReceipt(r.saleId(),r.receiptNumber());});t.setOnFailed(e->{loading.hide();AlertUtil.error("Sale rolled back",t.getException()==null?"The sale could not be completed.":t.getException().getMessage());});Thread x=new Thread(t,"complete-sale");x.setDaemon(true);x.start();}catch(NumberFormatException e){AlertUtil.warning("Invalid payment","Enter a valid paid amount.");}}
    private void showReceipt(int saleId,String receiptNumber){Task<String> task=new Task<>(){protected String call()throws Exception{return receiptService.render(saleId);}};task.setOnSucceeded(e->ReceiptPreviewDialog.show(this,task.getValue(),receiptNumber+".txt"));task.setOnFailed(e->AlertUtil.warning("Receipt preview unavailable","The sale completed, but the receipt preview could not be generated."));Thread thread=new Thread(task,"pos-receipt");thread.setDaemon(true);thread.start();}
    private record LookupData(List<QueryDAO.Option> categories,List<QueryDAO.Option> customers){}

}
